
/**
 * Generated by framework_parser.py for: Convention on the Rights of the Child
 * This function injects a complete analysis panel into a target container.
 * @param {targetContainerId: string, getTranscriptText: function, onAnalyze: function} options
 * - targetContainerId: The ID of the DOM element where the panel's button should be injected.
 * - getTranscriptText: A function that returns the current transcript text to be analyzed.
 * - onAnalyze: A callback function that receives the full prompt package for AI processing.
 */
function injectConventionOnTheRightsOfTheChildPanel(options) {
    const { targetContainerId, getTranscriptText, onAnalyze } = options;

    const uiText = {
        title: 'Convention on the Rights of the Child Analysis',
        description: 'Analyze the current transcript for specific violations of the Convention on the Rights of the Child. You can edit the prompt below.',
        buttonText: 'Analyze with Convention on the Rights of the Child',
        defaultPrompt: `Analyze the provided transcript and identify behaviors that represent specific violations of the Convention on the Rights of the Child.

KEY SECTIONS FOR ANALYSIS:
- **Non-Discrimination**: 1. States Parties shall respect and ensure the rights set forth in the present Convention to each child within their jurisdiction without discrimination of any kind, irrespective of the child's or his or her parent's or legal guardian's race, colour, sex, language, religion, political or other opinion, national, ethnic or social origin, property, disability, birth or other status. 2. States Parties shall take all appropriate measures to ensure that the child is protected against all forms of dis...
- **Best Interests of the Child**: 1. In all actions concerning children, whether undertaken by public or private social welfare institutions, courts of law, administrative authorities or legislative bodies, the best interests of the child shall be a primary consideration. 2. States Parties undertake to ensure the child such protection and care as is necessary for his or her well-being, taking into account the rights and duties of his or her parents, legal guardians, or other individuals legally responsible for him or her, and, t...
- **Right to Life and Development**: 3 1. States Parties recognize that every child has the inherent right to life. 2. States Parties shall ensure to the maximum extent possible the survival and development of the child. Article 7 1. The child shall be registered immediately after birth and shall have the right from birth to a name, the right to acquire a nationality and. as far as possible, the right to know and be cared for by his or her parents. 2. States Parties shall ensure the implementation of these rights in accordance with...
- **Right to Name and Nationality**: 1. The child shall be registered immediately after birth and shall have the right from birth to a name, the right to acquire a nationality and. as far as possible, the right to know and be cared for by his or her parents. 2. States Parties shall ensure the implementation of these rights in accordance with their national law and their obligations under the relevant international instruments in this field, in particular where the child would otherwise be stateless. Article 8 1. States Parties unde...
- **Right to Identity**: 1. States Parties undertake to respect the right of the child to preserve his or her identity, including nationality, name and family relations as recognized by law without unlawful interference. 2. Where a child is illegally deprived of some or all of the elements of his or her identity, States Parties shall provide appropriate assistance and protection, with a view to re-establishing speedily his or her identity. Article 9 1. States Parties shall ensure that a child shall not be separated from...
- **Protection from Separation**: 1. States Parties shall ensure that a child shall not be separated from his or her parents against their will, except when competent authorities subject to judicial review determine, in accordance with applicable law and procedures, that such separation is necessary for the best interests of the child. Such determination may be necessary in a particular case such as one involving abuse or neglect of the child by the parents, or one where the parents are living separately and a decision must be m...

FOR EACH POTENTIAL VIOLATION IDENTIFIED:
1. Quote the exact transcript excerpt (with timestamp and speaker).
2. Reference the specific principle, article or section of the framework that was violated.
3. Briefly analyze the nature and severity of the violation.

PROVIDE A FINAL SUMMARY: Does this pattern of behavior indicate that the responsible entity is systematically failing to comply with the Convention on the Rights of the Child?`
    };

    const systemPrompt = 'You are a specialized legal and compliance analyst. Your task is to analyze dialogues strictly in the context of Convention on the Rights of the Child, identifying specific violations with precise references. Your output must be structured, factual, and cited.';

    const container = document.getElementById(targetContainerId);
    if (!container) {
        console.error(`[Panel Injector] Target container with ID #${targetContainerId} not found.`);
        return;
    }

    // 1. Create the activation button
    const analysisButton = document.createElement('button');
    analysisButton.textContent = uiText.buttonText;
    analysisButton.className = 'btn btn-special-analysis'; // Add your own styling
    container.appendChild(analysisButton);

    // 2. Create the analysis panel (initially hidden)
    const panel = document.createElement('div');
    panel.className = 'analysis-panel'; // Style this class
    panel.style.display = 'none';
    panel.innerHTML = `
        <div class="panel-header">
            <h3>${uiText.title}</h3>
            <button class="close-btn">&times;</button>
        </div>
        <p>${uiText.description}</p>
        <textarea class="prompt-textarea">${uiText.defaultPrompt}</textarea>
        <button class="execute-analysis-btn">Run Analysis</button>
    `;
    document.body.appendChild(panel); // Append to body to act like a modal

    // 3. Add event listeners
    analysisButton.addEventListener('click', () => {
        panel.style.display = 'block';
    });

    panel.querySelector('.close-btn').addEventListener('click', () => {
        panel.style.display = 'none';
    });

    panel.querySelector('.execute-analysis-btn').addEventListener('click', () => {
        if (typeof onAnalyze !== 'function' || typeof getTranscriptText !== 'function') {
            alert('Analysis function not configured correctly.');
            return;
        }
        
        const userPrompt = panel.querySelector('.prompt-textarea').value;
        const transcriptText = getTranscriptText();

        // Package everything for the AI
        const analysisPackage = {
            system_prompt: systemPrompt,
            user_prompt: userPrompt,
            transcript: transcriptText,
            framework: 'Convention on the Rights of the Child'
        };

        onAnalyze(analysisPackage);
        panel.style.display = 'none'; // Hide panel after starting analysis
    });

    console.log(`Panel for Convention on the Rights of the Child injected and ready.`);
}
